#include "ligra.h"
#include "math.h"
#include <iomanip>

// Delta-based ("push") PageRank. Instead of recomputing every rank from
// scratch each round, only the *change* in rank (Delta) is propagated, and only
// vertices whose Delta is still significant relative to their accumulated rank
// stay on the frontier. This makes later rounds cheap once most of the graph
// has converged.

//pushes the change in rank of each active vertex to its out-neighbors
template <class vertex>
struct PR_F {
  double* Delta, *nghSum;
  vertex* V;
  PR_F(double* _Delta, double* _nghSum, vertex* _V) :
    Delta(_Delta), nghSum(_nghSum), V(_V) {}
  inline bool update(uintE s, uintE d) {
    double oldVal = nghSum[d];
    nghSum[d] += Delta[s]/V[s].getOutDegree();
    return oldVal == 0.0; //true only for the first contribution into d
  }
  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
    volatile double oldV, newV;
    do { //fetch-and-add on a double
      oldV = nghSum[d]; newV = oldV + Delta[s]/V[s].getOutDegree();
    } while(!CAS(&nghSum[d],oldV,newV));
    return oldV == 0.0;
  }
  inline bool cond (uintE d) { return cond_true(d); }
};

//vertex map to compute the initial Delta of each vertex (first round only)
struct PR_Vertex_F_FirstRound {
  double damping, addedConstant, one_over_n, epsilon2;
  double* p, *Delta, *nghSum;
  PR_Vertex_F_FirstRound(double* _p, double* _Delta, double* _nghSum,
                         double _damping, double _one_over_n, double _epsilon2) :
    p(_p), Delta(_Delta), nghSum(_nghSum), damping(_damping),
    one_over_n(_one_over_n), addedConstant((1-_damping)*_one_over_n),
    epsilon2(_epsilon2) {}
  inline bool operator () (uintE i) {
    Delta[i] = damping*nghSum[i]+addedConstant;
    p[i] += Delta[i];
    Delta[i] -= one_over_n; //subtract off the delta from initialization
    return (fabs(Delta[i]) > epsilon2*p[i]); //stay active if change is large
  }
};

//vertex map to update Delta and p (rounds after the first)
struct PR_Vertex_F {
  double damping, epsilon2;
  double* p, *Delta, *nghSum;
  PR_Vertex_F(double* _p, double* _Delta, double* _nghSum,
              double _damping, double _epsilon2) :
    p(_p), Delta(_Delta), nghSum(_nghSum), damping(_damping),
    epsilon2(_epsilon2) {}
  inline bool operator () (uintE i) {
    Delta[i] = nghSum[i]*damping;
    if (fabs(Delta[i]) > epsilon2*p[i]) { p[i] += Delta[i]; return 1; }
    else return 0; //change too small to be worth propagating
  }
};

//resets nghSum
struct PR_Vertex_Reset {
  double* nghSum;
  PR_Vertex_Reset(double* _nghSum) :
    nghSum(_nghSum) {}
  inline bool operator () (uintE i) {
    nghSum[i] = 0.0;
    return 1;
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  long maxIters = P.getOptionLongValue("-maxiters",100);
  const long n = GA.n;
  const double damping = 0.85, epsilon = 0.0000001, epsilon2 = 0.01;

  double one_over_n = 1/(double)n;
  double* p = newA(double,n);
  double* Delta = newA(double,n);
  double* nghSum = newA(double,n);
  bool* frontier = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) {
    p[i] = 0.0;
    Delta[i] = one_over_n; //initial delta propagation from each vertex
    nghSum[i] = 0.0;
    frontier[i] = 1;
  }}

  vertexSubset Frontier(n,n,frontier);
  bool* all = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) all[i] = 1;}
  vertexSubset All(n,n,all); //all vertices, used as the vertexFilter input

  long iters = 0;
  while(iters < maxIters) {
    iters++;
    // (a) push Delta along the out-edges of the active vertices. The output
    // frontier is computed by the vertexFilter below, so no_output is used.
    edgeMap(GA,Frontier,PR_F<vertex>(Delta,nghSum,GA.V),GA.m/20, no_output | dense_forward);
    // (b) turn the accumulated neighbor sums into new Deltas, fold them into p,
    // and keep only the vertices whose Delta is still significant
    vertexSubset active = (iters == 1) ?
      vertexFilter(All,PR_Vertex_F_FirstRound(p,Delta,nghSum,damping,one_over_n,epsilon2)) :
      vertexFilter(All,PR_Vertex_F(p,Delta,nghSum,damping,epsilon2));
    //compute L1-norm of Delta (nghSum is reused as scratch space, then reset)
    {parallel_for(long i=0;i<n;i++) nghSum[i] = fabs(Delta[i]);}
    double L1_norm = sequence::plusReduce(nghSum,n);
    if(L1_norm < epsilon) { active.del(); break; }
    //reset nghSum for the next round
    vertexMap(All,PR_Vertex_Reset(nghSum));
    Frontier.del();
    Frontier = active; //set new frontier
  }

  double sum = sequence::plusReduce(p,n);
  cout << setprecision(10) << "PageRankDelta sum: " << sum << endl;
  cout << "PageRankDelta iters: " << iters << endl;

  Frontier.del(); All.del();
  free(p); free(Delta); free(nghSum);
}
